targets.expr:
sum by (job,instance) (
  system_filesystem_usage_bytes{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mountpoint="/"}
)
or
sum by (job,instance) (
  system_filesystem_usage{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mountpoint="/"}
)

100 * (
  sum by (job,instance) (
  system_memory_utilization_ratio{job=~".+",job=~"$job",instance=~"$instance", state="used"}
)
)
or
100 * (
  sum by (job,instance) (
  system_memory_utilization{job=~".+",job=~"$job",instance=~"$instance", state="used"}
)
)

100 * (
  max by (job,instance,mountpoint) (
  system_filesystem_utilization_ratio{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mode!="ro"}
)
)
or
100 * (
  max by (job,instance,mountpoint) (
  system_filesystem_utilization{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mode!="ro"}
)
)
